# -*- coding: utf-8 -*-
"""
drone_cad.py — **실물 형상에 맞춘 고충실도 드론 CAD** (trimesh + manifold3d + shapely + scipy)
=================================================================================================
기존 `drones.py` 의 파라메트릭 메쉬는 프리미티브(원기둥·다각기둥)를 **겹쳐 쌓은** 것이라
  · 동체가 각진 다각기둥이었고(실물은 매끈한 눈물방울),
  · 짐벌·카메라가 상자였고(Mavic 4 는 **구형 Infinity 짐벌**),
  · 착륙장치·RTK 안테나 같은 실루엣 특징이 없었고,
  · **불리언이 없어** 겹친 파트의 **내부 면이 그대로 남아** PO/SBR 이 헛세는 원인이 됐다.

이 모듈은 `cadkit.py`(trimesh/manifold3d/shapely/scipy)로 **실물 사진·제원에 맞춰** 다시 만든다.

■ 기종별 실루엣 (공식 자료·제품 사진 기준)
  mini5pro   초슬림 접이식. 낮고 길쭉한 동체. 앞팔은 수평으로 펴지고 뒷팔은 아래로. 착륙장치 없음.
             전방 하단에 작은 2축 짐벌(1인치 센서).
  mavic4pro  **구형 "Infinity 짐벌"** — 매달린 게 아니라 **기수와 일직선인 볼 마운트**, 360° 회전.
             볼 전면에 **3개 렌즈**(100MP 광각 + 중망원 + 망원). 넓은 눈물방울 동체 + 상단 배터리 캐노피.
  matrice4e  Mavic 3 계열 동체 + **상단 RTK 돔**. 전방 3축 짐벌(측량 페이로드). 작은 발 4개.
  s1000plus  옥토. **원형 카본 센터프레임(상·하판)** + 8암. **긴 접이식 착륙다리**. 벨리 짐벌.
  phantom4   고정암 일체형 흰 셸. **일체형 스키드 착륙다리**. 코 아래 매달린 짐벌(방진판).
             기수에 비전센서.

■ 왜 이게 RCS 에 중요한가
  RCS 는 **외형(투영면적)과 재질 분포**가 결정한다. 실루엣이 틀리면 σ 가 틀린다.
  그리고 **불리언 합집합**으로 겹친 파트의 내부 면을 녹여 없애면, SBR 이 가림으로 걸러내기 **전에**
  애초에 그런 면이 존재하지 않게 된다 — 더 정확하고 더 빠르다.

■ 공식 외형 정합
  마지막에 `spec.envelope_mm`(DJI 공식 언폴드·프롭제외 L×W×H)에 프레임 바운딩박스를 맞춘다.
  (drones.frame_fit_scale 과 같은 규약)
"""
from __future__ import annotations

import numpy as np
import trimesh

from cadkit import (Assembly, loft, spline_sections, superellipse, rounded_rect, sweep,
                    revolve, smooth, box, cyl, sphere, capsule, rot_z, mv)


# --------------------------------------------------------------------------- #
#  ⭐⭐ 2026-08-16 — 메쉬 결함 **수리 스위치** 중 이 파일이 담당하는 것 (감사 §⑤ 2층)
# --------------------------------------------------------------------------- #
#  ⭐ **스위치의 정본은 `geom.py` 머리말**이다(환경변수 `MESH_FIX`). 스위치가 두 군데 있으면
#    «켰는데 반만 켜지는» 사고가 나므로, 여기서는 그 스위치를 **읽기만** 하고 새로 만들지 않는다.
#      MESH_FIX=battery python src/mesh_check.py        ← 공용 스위치(전역)
#      build_frame_cad(spec, mesh_fix='battery')        ← 호출 단위 명시(전역 스위치와 무관)
#      build_frame_cad(spec, mesh_fix=False)            ← 이 호출만 강제로 끔
#  ⭐ 기본(인자 없음 · 환경변수 없음) = **꺼짐** = 예전 메쉬와 **비트동일**.
#    켜면 형상이 실제로 바뀌므로 비트동일이 깨진다 — 그것이 **의도된 것**이고, 두 방향을
#    회귀 시험이 증명한다(benchmark/regress_mesh_fix_battery_0816.py).
#  ⚠ 명시 호출에서 **아무도 모르는 id** 를 주면 즉시 ValueError — 오타를 조용히 무시하면
#    «수리를 켠 줄 알았는데 안 켜진» 결과가 원장에 들어간다(materials._spec 와 같은 규약).
MESH_FIX_TOKENS = {
    "battery": (
        "'battery' 그룹의 부품들을 불리언 합집합으로 **하나로** 만든다. 셸형 공용 경로에서 "
        "배터리 팩 상자와 v2 구조판 상자가 서로 파고들어(mini2 49.96 % · phantom4 49.46 % · "
        "mavic4pro 48.12 % · mini5pro 47.89 %) 그 매몰면을 PO 가 이중계상한다 — PO 는 가림을 "
        "안 보기 때문이다(rcs_po.py 가 스스로 선언). 치수는 **하나도 안 바꾼다**(기종별 실측 "
        "치수가 없으므로 상자를 옮기는 것은 «지어내기» 다). 합집합은 겹친 자리의 내부 면만 없앤다."),
    "i4": (
        "묻힌 캐노피(감사 I4) — 셸형 기체의 'canopy' 를 'body' 와 **불리언 합집합**해 껍질을 "
        "하나로 만든다. 실물 근거: DJI 매뉴얼 그림(mavic4pro m02 · phantom4 공식 정면)이 "
        "몰드 셸 **한 장**을 보여 주고 배터리는 셸 윤곽에 맞춰 뒤에서 꽂힌다 — 셸 안에 "
        "두 번째 닫힌 껍질은 실물에 없다. 코드 주석도 phantom3·mini2 에서 «솟은 캐노피가 "
        "없는데 공용 경로가 무조건 붙인다» 고 스스로 선언한다. 묻힌 비율은 mavic4pro·phantom3 "
        "100 % · phantom4 92.7 % · mini2 86.4 % · mini5pro 86.2 % · typhoonh480 74.6 % · "
        "matrice4e 69.2 %. ⭐완전 매몰이면 합집합 결과가 곧 body 이므로 **캐노피 그룹만 빼고 "
        "body 삼각형은 안 건드린다**(그래야 수리의 σ 변화가 캐노피만의 것이 된다). 부분 노출은 "
        "합집합해서 **노출부만** 남긴다 — 통째로 빼면 실루엣이 바뀐다. 대가: 그 기체의 "
        "'canopy' 그룹이 사라져 부품별 σ 분해표의 칸이 하나 없어진다(재질은 둘 다 plastic 이라 "
        "|Γ| 는 안 바뀐다)."),
    "m4": (
        "x500v2 암 튜브 관통(감사 m4의 절반) — 나일론 클램프('accent') 솔리드 **안에 묻힌** "
        "카본 암 튜브('arm') 구간을 불리언 차집합으로 잘라낸다(14,274 mm²). 근거: 열린 프레임은 "
        "`shell_groups=()` 라 SBR 이 나일론을 **불투명**으로 보고 그 안의 튜브를 절대 못 맞힌다 "
        "— 수리는 PO 기하를 기본 엔진이 보는 것과 같게 만든다. 치수는 하나도 안 바꾼다. "
        "⛔같은 감사 항목의 «동일평면 5,409 mm²»(나일론 시트 윗면 z=4 ↔ 카본판 아랫면 z=4)는 "
        "**안 고친다** — 제조사 STEP(y_step 20.0/22.0)이 둘이 맞닿아 있다고 말하므로 0.1 mm "
        "띄우기는 실물에서 멀어지고 PO 이중계상도 안 없어지며, 합치면 재질 경계(carbon 0.90 ↔ "
        "plastic 0.28, 10.14 dB)가 사라져 없애는 오차보다 큰 오차가 생긴다(원장에 측정치 있음)."),
}


def normalize_mesh_fix(mesh_fix=None) -> frozenset:
    """지금 켜져 있는 **이 파일 담당** 수리 id 집합.

    mesh_fix=None(기본)이면 공용 스위치(`geom.mesh_fix_set()` = 환경변수 MESH_FIX)를 읽는다.
    명시로 주면 그것만 본다 — False/() 는 «이 호출만 강제로 끔».
    반환이 frozenset 이라 캐시 키로 그대로 쓸 수 있다(drones.frame_fit_scale)."""
    from geom import mesh_fix_set, MESH_FIX_KNOWN     # 스위치 정본
    if mesh_fix is None:                              # 전역 스위치를 따른다
        toks, strict = mesh_fix_set(), False
    elif mesh_fix is False:
        return frozenset()
    elif mesh_fix is True:
        toks, strict = {"all"}, False
    else:
        toks = ([t for t in str(mesh_fix).replace(";", ",").replace(",", " ").split()]
                if isinstance(mesh_fix, str) else [str(t) for t in mesh_fix])
        strict = True
    out = set()
    for t in toks:
        t = t.strip().lower()
        if not t:
            continue
        if t == "all":
            out.update(MESH_FIX_TOKENS)
            continue
        if t in MESH_FIX_TOKENS:
            out.add(t)
            continue
        #  다른 파일 담당 id(i5·m6 …)는 여기선 할 일이 없다 — 조용히 지나간다.
        if strict and t not in MESH_FIX_KNOWN:
            raise ValueError(
                f"drone_cad: 아무도 모르는 mesh_fix id {t!r}. 아는 id = "
                f"{sorted(set(MESH_FIX_KNOWN) | set(MESH_FIX_TOKENS))} (+ 'all'). "
                f"⛔오타를 조용히 무시하면 «수리를 켠 줄 알았는데 안 켜진» 결과가 원장에 들어간다.")
    return frozenset(out)


# --------------------------------------------------------------------------- #
#  공통 부품
# --------------------------------------------------------------------------- #
def _motor_bell(r, h, seg=36):
    """모터 벨 — 아래가 잘록하고 위가 부푼 실제 아웃러너 형상(회전체)."""
    pr = np.array([
        [0.00, 0.00], [r * 0.55, 0.00], [r * 0.72, h * 0.10],
        [r * 0.94, h * 0.22], [r * 1.00, h * 0.55], [r * 0.96, h * 0.82],
        [r * 0.80, h * 0.95], [r * 0.42, h * 1.00], [0.00, h * 1.00],
    ])
    return revolve(pr, seg=seg)


def _prop_hub(r, h, seg=28):
    pr = np.array([[0, 0], [r, 0], [r * 0.92, h * 0.6], [r * 0.55, h], [0, h]])
    return revolve(pr, seg=seg)


# --------------------------------------------------------------------------- #
#  블레이드 법칙 — **실물 참조 프롭 3종 측정에서 유도** (2026-07-28)
# --------------------------------------------------------------------------- #
#  근거 원장: outputs/reference_props.json  (생산자 benchmark/measure_reference_props.py)
#  측정 대상: Holybro 1345(13in) · 3DR Solo(10in) · Yuneec Typhoon H480
#  측정법: **원통 단면**(프로펠러 단면의 정식 정의). 평면절단은 스윕 큰 프롭에서 팁을 빗나가고
#          비폐곡면 어셈블리에서 폴리곤이 안 나와 못 쓴다.
#
#  ⛔⛔ **2026-08-16 정정 — 아래 «없다» 는 지금 거짓이다.**
#    옛 문장: «저장소에 DJI 프로펠러 실물 기하는 하나도 없다». 2026-08-07 에 들어온
#    assets/meshes/reference/WM161_zhankai_1k.glb (DJI Mini 2 공식 3D 모델) 안에 **날 8장 +
#    허브 4개**가 실재한다(디스크 지름 118.4~119.7 mm ↔ 공칭 4726F 119.4 mm, −0.9~+0.3 %).
#    ⇒ 이 법칙이 3DR Solo 를 대리 기준으로 삼은 **근거 자체가 무너졌다**.
#    ⇒ 감사 결과(docs/MESH_AUDIT_0816.md) — ⭐**아래는 2026-08-16 적대 검증(독립 3잣대 재측정)이
#      정정한 판이다.** 감사 원문의 네 수·문구는 무너졌고 나머지는 살아남았다.
#      · **살아남음(가장 튼튼한 숫자)**: 외곽이 좁다 — **0.60~0.96R 면적비 0.66 = −3.66 dB**
#        (세 독립 잣대가 0.5 % 안에서 일치). 시위 정점이 안쪽(우리 0.31R ↔ DJI 0.45R).
#        피치 기준 반경이 다르다(우리 0.63R ↔ DJI 국소피치 최대 0.73R·표준 규약 0.75R,
#        외곽 비틀림 폭 9.58° ↔ 5.68°). c_max/R 이 실물마다 0.177~0.273 으로 1.54 배 —
#        단일 상수 0.25 는 근거가 없다. ⭐스윕각 인공물 반증을 시도했으나 **실패**했다
#        (cosΛ 보정해도 시위비 0.6514 → 0.6499) — 시위 비교는 잣대 인공물이 아니다.
#      · ⛔**무너짐 ①** «날 면적 −29 %(−2.97 dB)» → **−20~−22 %(−2.0~−2.2 dB)** 다. 공통 반경
#        창에서 세 잣대가 0.781/0.784/0.787 로 맞고, 감사 자신의 면적표(0.7893)와도 맞는다.
#        재현이 안 된 것은 0.710 하나뿐이었다. ⇒ **총면적 대신 위 외곽 밴드 값을 인용할 것.**
#      · ⛔**무너짐 ②** «DJI 날은 0.175R 부터라 우리 뿌리 여유를 빼야 한다» — 거짓. DJI 날은
#        **0.034R** 까지 있고 0.175R 아래 면적이 우리보다 **더** 많다(13.6 % ↔ 10.0 %).
#      · ⛔**무너짐 ③** «Solo 는 유일한 이상치» → 참조 CAD 3종이 **2:1 로 갈린다**. 정규화 시위
#        @0.70R: 1345 **0.4896** · Solo 0.5754 ↔ Yuneec 0.8669 · DJI Mini2 0.8638.
#        **1345 가 Solo 보다 더 뿌리 편중형**이다(감사 표에 1345 행이 빠져 있었다).
#        정확한 진술: «참조 CAD 는 뿌리 편중형 2 : 늦은 정점형 1 로 갈리고 **DJI 는 늦은 정점형**».
#      · ⛔**무너짐 ④** «c_max/R 은 크기와 반비례» — 스피어만 **−0.05**(무상관). 같은 크기급
#        안에서도 0.1769~0.2726 로 전 범위를 덮는다. ⇒ **크기에서 보간하면 안 된다** — 프롭마다 실측.
#      · ⚠파급: mini2 note 의 «뒤 로터 코닝 틸트» 는 **회전축을 안 기울이고 잰 인공물일 수 있다**
#        (참 로터축은 월드 +y 가 아니라 앞 2.97°·뒤 5.00° 기울어져 있다 — 모터축·프롭너트 두
#        부품이 0.012° 안에서 일치). `prop_pitch_in` 2.6 을 다시 쓰기 전에 재검사할 것.
#      팁이 실물보다 뾰족하다는 항목은 유지된다.
#    ⇒ **1차 앵커를 DJI Mini 2 공식 CAD 로 교체해야 한다.** 교체 전까지 이 법칙으로 낸
#      절대 세기·기종 간 비교에는 위 오차 크기를 꼬리표로 단다. 권고값은 감사 문서 §L 참조.
#    ⚠ 여전히 참인 것: 세 참조 CAD 는 계측 스캔이 아니라 시뮬레이터용이고, 절대 σ 앵커는
#      계속 docs/DRONE_SPECS.md §4 의 실측 문헌에 의존한다.
#
#  ⛔ **폐기된 옛 근거**: "chord_max 0.26R — 실물 1345 는 0.30R 이라 소비자용이 더 슬림".
#     0.30R 은 1345 STL 의 **bbox x-폭**(52.03/173.0)이지 시위가 아니다. 실측 시위는
#     1345 0.225R · Solo 0.273R 이라, 옛 주장은 방향까지 뒤집혀 있었다.

# 시위 분포 c(r/R)/c_max — 3DR Solo 측정(소비자용 쿼드 프롭, DJI 급에 가장 가까움)
#   ⚠ 옛 코드는 이 곡선을 tt(=루트~팁 정규화)에 걸어 피크가 r/R=0.396 에 있었다.
#     실측 피크는 Solo 0.275 · 1345 0.300 이라 **r/R 기준으로 다시 건다.**
CHORD_RR = (0.00, 0.070, 0.15, 0.20, 0.25, 0.30, 0.35, 0.40,
            0.50, 0.60, 0.70, 0.80, 0.90, 0.95, 1.00)
CHORD_FRAC = (0.38, 0.45, 0.725, 0.868, 0.978, 0.989, 0.922, 0.865,
              0.760, 0.665, 0.577, 0.489, 0.403, 0.352, 0.10)
CHORD_MAX_OVER_R = 0.25       # 실측 Solo 0.273 · 1345 0.225 의 중간 (옛 0.26 은 bbox 유래)

# 국소 기하피치 분포 k(r/R) = P_local(r) / P_nominal — 3DR Solo 측정
#   실물 프롭은 **정피치가 아니다.** 공칭 피치는 ~0.5R 에서 맞는 기준값이고, 국소 피치는
#   루트에서 낮게 시작해 0.6~0.7R 에서 최대가 됐다가 팁에서 다시 떨어진다.
#   Solo 실측 국소피치[in]: 1.07(0.15R) 2.92(0.30) 4.50(0.50) 4.99(0.70) 4.56(0.80) 3.37(0.90)
#   ⛔ 옛 코드는 k≡1 (정피치)이라 θ(0.070R)=57.6~68.3° 라는 **물리적으로 불가능한 루트**를 만들었다.
#      실측 최대 트위스트: Solo 17.2° · 1345 20.2° · Typhoon 29.6° — 어느 실물도 30° 를 안 넘는다.
PITCH_RR = (0.00, 0.05, 0.10, 0.15, 0.20, 0.25, 0.30, 0.35, 0.40,
            0.50, 0.60, 0.70, 0.80, 0.90, 0.95, 1.00)
PITCH_K = (0.07, 0.08, 0.13, 0.238, 0.369, 0.516, 0.649, 0.751, 0.833,
           1.000, 1.106, 1.109, 1.013, 0.748, 0.732, 0.72)

# 두께비 t/c — 루트 → 팁. 실측 범위: 1345 5.9~9.3% · Solo 6.1~8.2% · Typhoon 8.6~12.8%
#   ⛔ 옛 값 9.2~13.5% 는 소비자용 프롭 셋 중 어느 것보다도 두꺼웠다.
TC_ROOT, TC_TIP = 0.095, 0.065

# 캠버(NACA-4 평균선) — 실측: 1345 8.32% · Solo 4.37% · Typhoon 6.80%,
#   피크 위치는 **셋 다 x/c ≈ 0.50**(0.49/0.52/0.51). p=0.5 면 평균선이 yc = 4m·x(1−x) 로 단순화된다.
#   ⛔ 옛 `_airfoil` 은 **대칭**이라 캠버가 정확히 0 이었고, docstring 은 그걸 "실제 프로펠러 단면"
#      이라고 불렀다. 실물 참조 셋이 전부 캠버를 갖는다.
#   RF 영향은 유계다(시위/λ ≤ 0.86, 캠버 곡률반경 0.17~1.23λ) — 방위평균 σ 로는 1 dB 미만.
CAMBER_M, CAMBER_P = 0.05, 0.50

#  ⭐⭐ 2026-08-16 **선언 — 위 파라미터와 «실제로 지어진 값» 은 다르다**(감사 m3).
#     버그가 아니다. 그런데 그 차이가 어디에도 안 적혀 있었던 것이 문제라 여기 박아 둔다.
#
#       | 항목        | 설정 파라미터        | 메쉬에서 실제로 재면 | 차이     |
#       |------------|--------------------|------------------|---------|
#       | 두께비 t/c  | TC_TIP~TC_ROOT 6.5~9.5 % | 6.3~11.5 %  | +19~21 % |
#       | 캠버        | CAMBER_M 5.0 %      | 6.4~7.3 %       | +29~46 % |
#
#     ⚠ 원인은 **캠버**다(측정 버그가 아니다). 캠버가 있는 익형은 «시위 좌표계에서 상면과
#       하면의 차» 가 NACA 의 두께 파라미터 t 보다 커진다 — 평균선이 휘어 있으니 위아래
#       봉우리가 시위선 기준으로 어긋나 더해지기 때문이다. 즉 t/c 파라미터는 «평균선에
#       수직으로 잰 두께» 이고, 실측 t/c 는 «시위선 기준 상하면 차» 다. **다른 잣대다.**
#
#     참조 밴드와 견주면: 실현 최대 t/c 11.3~11.5 % 는 소비자 참조 둘(1345 9.3 % ·
#     Solo 8.2 %)보다 여전히 두껍고, Typhoon 밴드(8.6~12.8 %) 안에는 든다.
#     ⇒ 인용 규칙: **파라미터 값을 «우리 날의 두께비» 라고 쓰지 말 것.** 둘 다 적거나,
#       실현값(6.3~11.5 %)을 쓸 것.


# --------------------------------------------------------------------------- #
#  ⭐⭐ 블레이드 «법칙 판» — 갈아끼울 수 있게 (2026-08-16, 감사 §⑤ 3층 13·15·16·17·18)
# --------------------------------------------------------------------------- #
#  왜 판으로 나누나
#    위의 상수들(CHORD_FRAC·PITCH_K·CHORD_MAX_OVER_R)로 지금까지의 **모든** 원장·리포트·덱이
#    나왔다. 감사가 그 상수의 근거를 무너뜨렸다고 해서 상수를 덮어쓰면 기존 수치가 통째로
#    바뀌고, 무엇이 왜 달라졌는지 되짚을 방법이 없어진다.
#    그래서 **덮어쓰지 않는다**. 현행 법칙에 `legacy` 라는 이름을 붙여 그대로 얼려 두고,
#    새 법칙을 `dji_mini2` 라는 **다른 이름으로 추가**한다. 고르는 것은 호출부의 몫이고
#    **기본값은 계속 `legacy`** 다 — 즉 인자를 안 주면 메쉬는 **비트 단위로 예전 그대로**다.
#    (정본을 언제 갈아끼울지는 파일럿으로 크기를 재고 나서 정할 일이지 이 파일이 정할 일이 아니다.)
#
#  용어 한 줄 풀이
#    · **시위(chord)**   날 단면의 앞전~뒷전 길이. 날의 «폭».
#    · **평면형(planform)** 위에서 본 날 윤곽 = 시위가 반경에 따라 어떻게 변하는가.
#    · **c_max/R**      최대 시위를 프롭 반경으로 나눈 값. 날이 얼마나 «통통한가».
#    · **국소 기하피치 k(r)** 반경 r 에서의 피치를 공칭 피치로 나눈 값. 1 이면 공칭 그대로.
#
#  판 목록
#    | 이름         | 시위 분포                 | c_max/R          | 팁                        | 피치   |
#    |-------------|--------------------------|------------------|---------------------------|--------|
#    | `legacy`    | 3DR Solo 실측(2026-07-28) | 전 기종 0.25 상수 | 0.10 (뾰족)                | legacy |
#    | `dji_mini2` | DJI Mini 2 공식 CAD 실측   | 기종별(아래 표)   | 0.20 (뭉툭) + 팁 단면 3배 조밀 | legacy |
#
#    ⚠ `dji_mini2` 판도 **피치는 legacy 를 쓴다.** 피치 법칙은 따로 고른다(`pitch_law` 인자) —
#      이유는 아래 PITCH_LAWS 주석에 적었다(감사 I7: 어림이 과했을 가능성이 크다).

#  ── 시위 분포 c(r/R)/c_max — DJI Mini 2 공식 CAD 4로터 평균 (감사 C4 · 원장 L.priority_1)
#     제품사진 blade0 이 ±4 % 안에서 독립 확인. 우리 legacy(Solo 유래)는 외곽에서 실물보다
#     27~39 % 좁고, 정점 위치도 0.30R(우리) ↔ 0.45R(실물)로 어긋나 있었다.
CHORD_RR_DJI_MINI2 = (0.00, 0.07, 0.15, 0.20, 0.25, 0.30, 0.35, 0.40, 0.45, 0.50,
                      0.55, 0.60, 0.65, 0.70, 0.75, 0.80, 0.85, 0.90, 0.95, 1.00)
CHORD_FRAC_DJI_MINI2 = (0.300, 0.420, 0.550, 0.662, 0.816, 0.912, 0.957, 0.987, 1.000, 0.997,
                        0.982, 0.953, 0.916, 0.866, 0.808, 0.744, 0.664, 0.579, 0.475, 0.200)
#     ⭐ 끝값 0.200 이 감사 I8(팁을 뭉툭하게)의 집행이다 — legacy 는 0.10 이라 실물보다 뾰족했고
#       (c/R @0.98R 실물 0.1028 ↔ 우리 0.0609), 마이크로도플러에서 **f_tip 밴드의 세기**를
#       정하는 것이 바로 그 팁 면적이다. ⚠ 그 스펙트럼 효과는 아직 커널로 안 쟀다(감사도
#       «σ 로는 소액, 스펙트럼 축은 안 쟀다» 라고만 적었다). 지금의 근거는 «형상을 실물에
#       맞춘다» 까지다.

#  ── 국소 기하피치 k(r/R) — DJI Mini 2 공식 CAD 실측 (감사 I7 · 원장 G 절)
#     legacy 는 공칭 피치의 기준 반경이 0.5R 인데, 프로펠러 공학의 표준 규약이자 실물 DJI 는
#     **0.75R** 이다(k 가 0.75R 에서 최대 1.015). 그 결과 legacy 날은 외곽(0.6~0.9R) 비틀림
#     폭이 9.2° 로 실물 5.5° 의 1.7 배다.
#     ⚠⚠ **기본으로 켜지 않는다.** 감사가 스스로 «어림이 과했을 가능성이 크다» 고 적었다 —
#       «플래시 봉우리 −2.2 dB» 는 계산이 아니라 어림이고, 커널 민감도(피치 ×1.25)는
#       +0.15~+0.82 dB 로 훨씬 작았다. 켜기 전에 **커널로 플래시 폭을 직접 재라**(감사 §⑤ 17).
#     ⚠ 0.25R 미만과 1.00R 은 **실측이 없다.** 둘의 외삽 방식이 서로 다르니 그대로 적어 둔다
#       (2026-08-16 적대검증에서 재계산해 확인):
#         · 0.25R 미만 — legacy 곡선 × **1.0523**(=0.543/0.516, 0.25R 의 실측/legacy 비).
#           0.070→0.074 · 0.080→0.084 · 0.130→0.137 · 0.238→0.250 · 0.369→0.388.
#         · 1.00R — 같은 비를 쓰면 0.758 이 되지만, 실제로 넣은 값은 **0.816** 이다.
#           0.95R 실측(0.830)에 legacy 의 국소비(0.720/0.732)를 이어붙인 값이다 —
#           팁에서 실측 곡선의 기울기를 잇는 쪽이 자연스럽기 때문이다.
#       ⇒ 어느 쪽이든 **어림**이다. 이 두 점을 실측이라고 인용하지 말 것.
#     ⚠ 0.60~0.70R 이 0.974 → 0.953 → 0.991 로 출렁이는데, 1k 로 간략화된 GLB 의 측정 잡음으로
#       보인다. 매끄럽게 다듬지 않고 **실측 그대로** 둔다(감사 권고를 그대로 집행한다).
PITCH_RR_DJI_MINI2 = (0.00, 0.05, 0.10, 0.15, 0.20, 0.25, 0.30, 0.35, 0.40, 0.45, 0.50,
                      0.55, 0.60, 0.65, 0.70, 0.75, 0.80, 0.85, 0.90, 0.95, 1.00)
PITCH_K_DJI_MINI2 = (0.074, 0.084, 0.137, 0.250, 0.388,            # ← 어림(실측 없음)
                     0.543, 0.674, 0.756, 0.821, 0.892, 0.929,     # ← 여기부터 DJI 실측
                     0.947, 0.974, 0.953, 0.991, 1.015, 0.993, 1.014, 0.949, 0.830,
                     0.816)                                        # ← 어림(실측 없음)

#  ── c_max/R 을 기종별로 (감사 I2). ⛔**시위 분포 교체와 반드시 한 묶음이다** ──────────
#     따로 하면 큰 프롭의 총면적이 튄다: DJI 평면형은 legacy 보다 ∫c dr 이 +17.2 % 크므로,
