#     [실측 없는 기종] 모르면 모른다고 하고, **총면적을 legacy 와 같게** 둔다:
#       c_max/R = 0.25 × ∫c_legacy dr / ∫c_dji dr   (root_frac 0.070 ~ 1.0 구간 수치적분)
