def resolve_chord_max_over_r(spec, blade_law: str = "legacy") -> tuple[float, str]:
    """이 기체·이 판에서 쓸 `c_max/R` 과 그 출처 한 줄을 돌려준다.

    순서: ① 스펙에 `prop_chord_max_over_r` 가 **있으면** 그것(명시 지정이 항상 이긴다)
          ② `legacy` 판이면 전 기종 공통 상수 0.25 (예전 그대로)
          ③ `dji_mini2` 판이면 실측표 → 없으면 면적중립값
    ⚠ ① 이 `None` 이 아니면 `legacy` 판의 메쉬도 바뀐다. 레지스트리에서 이 필드를 채우는
      것은 «기존 원장과 다른 메쉬를 만들겠다» 는 선언이므로, 지금은 **아무 기종에도 안 채워
      두었다**(전 기종 None → 비트동일)."""
    v = getattr(spec, "prop_chord_max_over_r", None)
    if v is not None:
        return float(v), "spec.prop_chord_max_over_r (명시 지정)"
    if blade_law == "legacy":
        return float(CHORD_MAX_OVER_R), "drone_cad.CHORD_MAX_OVER_R (전 기종 공통 0.25)"
    key = getattr(spec, "key", None)
    if blade_law == "per_airframe":
        #  ⭐ 그 기체의 순정 프롭에서 잰 값. **설계 시위 축**이다(사진 유래면 다리 ×1.031 포함).
        w = getattr(spec, "prop_law_cmax_over_r", None)
        if w is not None:
            g = getattr(spec, "prop_law_grade", "?")
            m = getattr(spec, "prop_law_model", "?")
            return float(w), f"기체별 실측 [{g}] {m} — drones.PROP_LAW_0816"
        #  없으면 아래의 dji_mini2 경로로 흘려보낸다(= 대리). 그 사실이 문자열에 남는다.
    if key in CHORD_MAX_OVER_R_MEASURED:
        val, why = CHORD_MAX_OVER_R_MEASURED[key]
        return float(val), f"실측: {why}"
    return (float(CHORD_MAX_OVER_R_AREA_NEUTRAL),
            "실측 없음 → 면적중립값(legacy 와 ∫c dr 이 같아지는 값). 실물 주장 아님.")


def resolve_chord_profile(spec, blade_law: str = "legacy"):
    """이 기체·이 판에서 쓸 **평면형**(시위 분포)과 그 출처 한 줄.

    돌려주는 것: `(chord_rr, chord_frac, 출처문자열)`. `chord_rr` 가 None 이면
    «판의 공용 곡선을 쓴다» 는 뜻이라 `_blade` 가 예전 그대로 동작한다.

    ⭐ 이 함수가 있는 이유: c_max/R(한 수)만 기종별로 바꾸고 곡선을 공용으로 두면
    «통통한 정도만 다른 같은 프로펠러» 가 된다. 봉우리 위치가 기종마다 0.29R(1157F)
    ~0.55R(1158F) 로 벌어지는데 그건 배율로 흉내 낼 수 없다."""
    if blade_law != "per_airframe":
        return None, None, f"BLADE_LAWS['{blade_law}'] 공용 곡선"
    rr = getattr(spec, "prop_law_chord_rr", None)
    fr = getattr(spec, "prop_law_chord_frac", None)
    if rr is None or fr is None:
        return (None, None,
                "⚠ 이 기체의 평면형이 레지스트리에 없다 → dji_mini2 공용 곡선으로 대리")
    g = getattr(spec, "prop_law_grade", "?")
    m = getattr(spec, "prop_law_model", "?")
    return tuple(rr), tuple(fr), f"기체별 실측 [{g}] {m} — drones.PROP_LAW_0816"


def blade_law_tag(blade_law: str = "legacy", pitch_law=None, max_edge_m=None) -> str:
    """산출물 파일명에 붙일 꼬리표. **기본값이면 빈 문자열**(= 꼬리표 없음)이라
    기존 파일 이름이 안 바뀐다. 다른 판으로 돌린 결과는 옛 샤드와 파일명이 갈린다."""
    parts = []
    if blade_law and blade_law != "legacy":
        parts.append(f"blade-{blade_law}")
    if pitch_law and pitch_law != "legacy":
        parts.append(f"pitch-{pitch_law}")
    if max_edge_m:
        parts.append(f"edge{float(max_edge_m) * 1000:.0f}mm")
    return ("_" + "_".join(parts)) if parts else ""


def mesh_max_edge_m(mesh) -> float:
    """메쉬의 **가장 긴 삼각형 모서리**[m]. 파장에 견주는 잣대다."""
    V = np.asarray(mesh.vertices, float)
    F = np.asarray(mesh.faces, np.int64)
    if len(F) == 0:
        return 0.0
    E = np.vstack([F[:, [0, 1]], F[:, [1, 2]], F[:, [2, 0]]])
    return float(np.linalg.norm(V[E[:, 0]] - V[E[:, 1]], axis=1).max())


def refine_to_max_edge(mesh, max_edge_m: float):
    """긴 모서리를 **쪼개기만** 한다 — 형상은 한 점도 안 움직인다 (감사 m5).

    왜 필요한가: PO 면적분은 삼각형 **안**의 위상을 상수로 본다. 그래서 삼각형이 파장에
    비해 크면 위상 표본이 모자란다. 지금 프롭은 «면 수» 가 로터당 3184~3200 장으로 **고정**
    돼 있는데 프롭 지름은 119 → 533 mm 로 4.5 배 변하므로, 큰 기체일수록 성기다
    (3.5 GHz 에서 mini2 λ/16.9 ↔ m350rtk **λ/3.8**).
    ⭐ 그런데 그 최장 모서리는 날의 로프트 격자가 아니라 **허브 윗면·아랫면의 부채꼴**과
      **날 뿌리 마감면**에서 나온다(둘 다 중심에서 가장자리로 뻗는 부채꼴이라 반지름만큼
      길다). 그래서 `n_sec`·`n_pts` 를 올려도 최장 모서리는 안 줄어든다 — 실측으로 확인했다.
      해결은 «다시 짓기» 가 아니라 **다 짓고 나서 긴 모서리만 쪼개기**다. 선형 세분은 평면
      삼각형을 평면 조각으로 나누므로 표면적·부피·법선이 **정확히 보존**된다.
    ⚠ 이것은 «메쉬 미세정밀화» 가 아니다. 감사가 말리는 것은 «형상 해상도를 올리는 것»
      (로프트 단면 늘리기)이고, 이건 **같은 형상의 위상 표본**을 늘리는 것이다."""
    V = np.asarray(mesh.vertices, float)
    F = np.asarray(mesh.faces, np.int64)
    v2, f2 = trimesh.remesh.subdivide_to_size(V, F, max_edge=float(max_edge_m))
    return trimesh.Trimesh(vertices=v2, faces=f2, process=False)


def _airfoil(chord, thick_ratio=0.10, pts=40, camber_m=CAMBER_M, camber_p=CAMBER_P):
    """NACA-4 익형 단면(y=시위, z=두께). **캠버 포함**(camber_m=0 이면 대칭).

    두께는 표준 NACA-4 분포, 평균선은 표준 NACA-4 2구간 포물선.
    좌표는 평균선에 **수직**으로 두께를 얹는 정식 구성(단순 상하 오프셋이 아니다)."""
    t = float(thick_ratio)
    m, pp = float(camber_m), float(camber_p)
    x = (1 - np.cos(np.linspace(0, np.pi, pts // 2))) / 2          # 코사인 클러스터링(앞전 촘촘)
    yt = 5 * t * (0.2969 * np.sqrt(x) - 0.1260 * x - 0.3516 * x**2
                  + 0.2843 * x**3 - 0.1015 * x**4)
    if m > 0:
        yc = np.where(x <= pp,
                      m / pp**2 * (2 * pp * x - x**2),
                      m / (1 - pp)**2 * ((1 - 2 * pp) + 2 * pp * x - x**2))
        dyc = np.where(x <= pp,
                       2 * m / pp**2 * (pp - x),
                       2 * m / (1 - pp)**2 * (pp - x))
        th = np.arctan(dyc)
        xu, yu = x - yt * np.sin(th), yc + yt * np.cos(th)
        xl, yl = x + yt * np.sin(th), yc - yt * np.cos(th)
    else:
        xu, yu, xl, yl = x, yt, x, -yt
    up = np.c_[xu, yu]
    lo = np.c_[xl[::-1], yl[::-1]]
    P = np.vstack([up, lo[1:-1]]) * chord
    P[:, 0] -= chord * 0.30                                         # 시위 30% 를 원점(피치축)으로
    from shapely.geometry import Polygon
    return Polygon(P)


def _blade(R, root_frac=0.14, chord_max=CHORD_MAX_OVER_R, pitch_deg=20.0, twist_deg=13.0,
           sweep_frac=0.10, n_sec=22, n_pts=36, pitch_m=None,
           law="legacy", pitch_law=None, tip_refine=None,
           chord_rr=None, chord_frac=None):
    """**진짜 익형 프로펠러 블레이드 1장** — 로프트(테이퍼 + 워시아웃 트위스트 + 시미터 스윕).
    +x = 스팬. 익형 단면을 스팬을 따라 회전(피치)·축소(테이퍼)·후퇴(스윕)시키며 잇는다.
      chord_max : **R 에 대한 비율**(0.26 = 최대시위 0.26·R). ⚠ 절대길이를 넣지 말 것.
      pitch_m   : 프로펠러 **기하 피치**[m] (1회전 전진량). 주면 각 단면 피치각을
                  θ(r)=atan(P/(2πr)) 로 **물리적으로** 준다(모델별로 다름). None 이면
                  pitch_deg/twist_deg 의 선형 워시아웃(구버전).
      law       : 시위 분포 판 이름 — `BLADE_LAWS` 참조. **기본 'legacy' = 예전 그대로**.
      pitch_law : 피치 분포 판 이름 — `PITCH_LAWS` 참조. None 이면 그 판의 기본값(둘 다 legacy).
      tip_refine: 마지막 로프트 구간을 몇 등분할지(감사 I8). None 이면 판의 기본값
                  (legacy 1 = 안 쪼갬 → 비트동일 / dji_mini2 3).
      chord_rr / chord_frac : ⭐2026-08-16 추가 — **이 기체 하나만의 평면형**을 직접 넘긴다.
                  둘 다 주면 `law` 의 곡선 대신 이것을 쓴다(판은 팁 세분 등 나머지만 정한다).
                  **둘 다 None 이 기본** → 예전 그대로. `PROP_LAW_0816` 참조.
    ⚠ 인자를 안 주면 **비트 단위로 예전과 같은 메쉬**가 나온다. 회귀 증명:
      `benchmark/regress_blade_law_bitidentical.py`."""
    from shapely import affinity as aff
    lw = BLADE_LAWS[law]
    pw = PITCH_LAWS[pitch_law or lw["pitch_default"]]
    n_ref = int(lw["tip_refine"] if tip_refine is None else tip_refine)
    c_rr = lw["chord_rr"] if chord_rr is None else tuple(chord_rr)
    c_fr = lw["chord_frac"] if chord_frac is None else tuple(chord_frac)
    r0 = root_frac * R
    xs = np.linspace(r0, R, n_sec)
    if n_ref > 1:
        #  ⭐ 감사 I8 — 팁 쪽 로프트 단면 간격을 좁힌다. legacy 는 마지막 두 단면이
        #    0.9511R → 1.000R 로 벌어져 있어 뭉툭한 팁을 표현할 해상도가 없다.
        #    맨 끝 구간만 n_ref 등분한다(나머지 스팬은 그대로 — 총 면 수가 거의 안 는다).
        step = xs[-1] - xs[-2]
        extra = xs[-2] + step * np.arange(1, n_ref) / n_ref
        xs = np.concatenate([xs[:-1], extra, xs[-1:]])
    tt = (xs - r0) / (R - r0)
    rr = xs / R                                                      # ⭐ r/R (tt 가 아니다)

    # 시위 분포 — **r/R 기준** 실측 곡선. 옛 코드는 tt 에 걸어 피크가 0.396R 이었다.
    c = np.interp(rr, c_rr, c_fr) * float(chord_max) * R
    if pitch_m is not None:
        # 국소 기하피치 분포 k(r/R) 를 곱한다 — 실물 프롭은 정피치가 아니다.
        k = np.interp(rr, pw["rr"], pw["k"])
        th = np.arctan(k * float(pitch_m) / (2 * np.pi * xs))
    else:
        th = np.radians(pitch_deg - twist_deg * tt)                 # 워시아웃(선형 근사, 구버전)
    yc = sweep_frac * R * np.sin(np.pi / 2 * tt)                    # 시미터 스윕

    rings = []
    for x, ci, ti, yi, rri in zip(xs, c, th, yc, rr):
        # 두께비 테이퍼(실측 대역 안) — 루트 9.5% → 팁 6.5%
        f = np.clip((rri - root_frac) / max(1e-9, 1.0 - root_frac), 0.0, 1.0)
        p = _airfoil(max(ci, 1e-4), thick_ratio=TC_TIP + (TC_ROOT - TC_TIP) * (1 - f))
        p = aff.rotate(p, np.degrees(ti), origin=(0, 0), use_radians=False)
        p = aff.translate(p, yi, 0.0)
        rings.append((float(x), p))
    return loft(rings, n_pts=n_pts, cap=True)


# --------------------------------------------------------------------------- #
#  열린 프레임 내부 산란체 — 실물 킷 부품치수를 **판 치수의 비율**로 적는다
# --------------------------------------------------------------------------- #
#  (가로, 세로, 높이) = (·L, ·W, ·gap).  앵커: Holybro X500 V2 Full Kit (판 144×144, 간격 28)
#    배터리 4S 5000 mAh LiPo      ≈ 145×43×25 mm  → (1.00, 0.30, 0.90) = 144.0×43.2×25.2
#    전원분배(PM02)+ESC 보드      ≈  45×30×12 mm  → (0.31, 0.21, 0.43) =  44.6×30.2×12.0
#    비행제어기 Pixhawk 6C(케이스) ≈  85×43×15 mm  → (0.59, 0.30, 0.54) =  85.0×43.2×15.1
#  ⚠ 비율은 X500 부품치수에 맞도록 **역산한 것**이다(비율 자체가 물리법칙은 아니다). 다른 열린
#    프레임에 그대로 쓰면 그 기체 부품과 어긋날 수 있다 — 그때는 스펙 필드로 승격할 것.
OPEN_BATTERY_FRAC = (1.00, 0.30, 0.90)
OPEN_ESC_FRAC = (0.31, 0.21, 0.43)
OPEN_FC_FRAC = (0.59, 0.30, 0.54)

# --------------------------------------------------------------------------- #
#  ⭐⭐ 내부 산란체 — **기종별 실측표** (2026-08-03)
# --------------------------------------------------------------------------- #
#  셸형의 기본 경로는 배터리·PCB·마그네슘판을 `bl/bw/bh` **비율 상자**로 넣는다(공용 리터럴,
#  기종별 근거 없음 — docs/MESH_METHOD.md §7.7 이 "σ 지배 부품인데 전부 손조정"이라고 적어 둔
#  바로 그 자리다). 여기에 기종 키가 있으면 그 대신 **mm 실측 상자**를 쓴다.
#  형식: (그룹, (Lx, Ly, Lz)[mm], (cx, cy, cz)[mm])  — 좌표는 z=0 = 암 허브 평면, +x = 기수.
#  ⚠ 'battery'·'pcb' 그룹은 `build_frame_cad` 말미의 불리언 union 목록에 **기본으로는 없다**.
#    그래서 이 표의 상자들은 **서로 겹치지 않게** 놓는다 — 겹치면 파묻힌 면이 그대로 남아
#    PO 가 그 면적을 이중계상한다(PO 는 가림을 안 본다. SBR 은 first-hit 이라 무관).
#  ⭐ 2026-08-16 — 공용 비율상자 경로(이 표에 없는 셸형 기종)는 그 규칙을 **안 지키고 있었다**:
#    배터리 팩 상자와 v2 구조판 상자가 47.9~50.0 % 겹친다(mini2·phantom4·mavic4pro·mini5pro).
#    ⇒ 선택 수리 `MESH_FIX=battery`(=mesh_fix='battery') 가 'battery' 를 union 목록에 넣어 그 이중계상을
#      없앤다(치수는 그대로). 기본은 꺼져 있고, 이 표를 받은 두 기종(phantom3·matrice4e)은
#      애초에 안 겹치므로 켜도 상자 두 개가 그대로 남는다.
INTERNALS = {
    #  ⭐⭐ Phantom 3 — 분해사진 실측. 이 기체의 내부 상수는 지금까지 전부 phantom4 상속이었다.
    #  (1) 인텔리전트 플라이트 배터리 (PH3-4480 mAh-15.2 V) — **금속 파우치 다발 + 하드케이스**
    #      · 폭 76 mm : 후면도의 노출 뒷면 76.1 mm ↔ 톱뷰 74.6 mm (두 장 독립, 2 % 이내)
    #      · 높이 45 mm : 후면도 뒷면 세로 46.6 mm (LED 4 + 전원버튼이 찍힌 그 면)
    #      · 길이 80 mm : 저면사진 `p33`(축척 0.10464 mm/px = 모터 대각 3345 px)에서 베이
    #        바닥이 766 px = 80.2 mm.  부피 검산 76×45×80 = 274 mL ↔ 68 Wh → 248 Wh/L,
    #        4S 파우치 팩으로 타당(120 mm 로 잡으면 0.85 g/mL 로 LiPo 치고 너무 가볍다).
    #      · 위치: 뒷면이 셸 꼬리(x = −89.6)에 맞으므로 중심 x = −49.6.
    #        z 는 후면도의 뒷면 상·하단(z = −2 … −47) 중앙 → −24.5.
    #  (2) 중앙 X 보드 (전원/ESC + 메인 컨트롤러 일체) — Phantom 3 의 **유일한 대형 PCB**.
    #      셸을 벗긴 톱다운 `t67`(축척 4.78 px/mm = 모터 사각 1183 px) 실측 bbox
    #      159(좌우) × 128(앞뒤) mm. 실물은 X 자라 그 bbox 를 꽉 채우지 않는다 →
    #      **면적 등가 직사각** 120 × 110 × 3 mm 로 넣는다(측정 bbox 안, 면적 ≈ 실보드).
    #      ⚠ 십자로 겹친 두 판이 형상은 더 닮지만 'pcb' 가 union 목록에 없어 내부 면이 남는다.
    #      z 는 암 허브 평면(보드가 암 뿌리 높이에 앉는다, `t29`·`t67`) → 0.
    #  (3) 금속 실드된 영상/전송 모듈 — 중앙 보드 위에 얹힌 검은 실드 상자. `t67` 에서
    #      210 × 160 px = 44 × 33 mm, 높이는 `t29` 사선컷에서 ~20 mm. 중심은 로터 중심보다
    #      13 mm 앞. **이것이 (구) '마그네슘 구조판' 자리를 대신한다** —
    #      ⛔ Phantom 3 에는 마그네슘 골격이 없다(그건 Phantom 4 의 대표 개선점이다.
    #         outputs/p3_specs.json `materials.shell_body_and_arms.critical_difference_from_phantom4`).
    #         옛 코드는 공용 v2 경로 때문에 있지도 않은 마그네슘 판을 넣고 있었다.
    "phantom3": (
        ("battery", (80.0, 76.0, 45.0), (-49.6, 0.0, -24.5)),
        ("pcb",     (120.0, 110.0, 3.0), (0.0, 0.0, 0.0)),
        ("battery", (44.0, 33.0, 20.0), (13.0, 0.0, 12.0)),
    ),
    #  ⭐⭐ Matrice 4E (2026-08-04, F11·F12) — 공용 비율상자 경로에서 빠져나온다.
    #  (1) 배터리 — **치수는 공표제원**: DJI Matrice 4 Series User Manual v1.2 p.103,
    #      BPX345-6741-14.76 = 145.47 × 60.6 × 46.3 mm, 400 g. 옛 비율상자는 122.49 ×
    #      61.61 × 49.01 로 길이가 −15.8 % 였다.
    #      위치는 **공식 CAD**(matrice4-M4T_v2.step)가 준다: 배터리 베이(솔리드 117) 앞 끝이
    #      x_ours = +70.10 이고, 팩 후면이 셸 꼬리(−75.59)와 같은 면이라는 사진 관찰
    #      (p05·p09·m13·m14)을 걸면 중심 −2.86 · 팩 앞면 +69.88 → **베이 앞끝과 0.2 mm 일치**
    #      (서로 독립인 두 사실의 교차검증). 세로는 베이 바닥 z=−6.14 에 얹혀 −6.15…+40.15.
    #      ⇒ 셸 안 최대 금속 덩어리이자 σ 지배 부품이다.
    #  (2)(3) pcb·구조판 — ⚠ **치수는 측정하지 않았다.** 옛 비율상자 크기를 그대로 두고
    #      정정된 셸 안으로 **옮기기만** 한다(근거는 배제뿐: 배터리가 z −6.15…+40.15 를
    #      차지하므로 남는 자리는 그 아래, 셸 벨리 −30.81 까지다). CAD 는 외장 모델이라
    #      메인보드가 없고 분해사진 t05~t08 에는 축척 앵커가 없다.
    #      ⛔ 리포트에 '실측' 으로 적으면 안 된다 — 이 둘은 **엔진 손잡이**다.
    #      겹침 여유: 배터리 바닥 −6.15 ↔ pcb 상단 −9.5 (3.35) · pcb 하단 −14.5 ↔ 판 상단
    #      −18.45 (3.95) · 판 하단 −25.55 ↔ 셸 벨리 −30.81 (5.26).
    "matrice4e": (
        ("battery", (145.47, 60.6, 46.3), (-2.9, 0.0, 17.0)),
        ("pcb",     (93.0, 53.6, 5.0),    (-2.9, 0.0, -12.0)),
        ("battery", (142.0, 67.6, 7.1),   (-2.9, 0.0, -22.0)),
    ),
}


# --------------------------------------------------------------------------- #
#  기종별 동체
# --------------------------------------------------------------------------- #
def _body_folding(L, W, H, nose_drop=0.18, tail_w=0.95, n_pow=2.9,
                  hw_f=None, hh_f=None, zo_f=None, smooth_iters=4):
    """접이식 소비자기(미니/마빅/매트리스) 공용 눈물방울 동체.
    코는 좁고 살짝 처지고, 허리에서 가장 넓고, 꼬리는 완만히 좁아진다.

    ⭐ 2026-07-30 사진대조 라운드: 단면 법칙을 **인자로 뺐다**. 기본값은 옛 하드코딩 배열
      그대로라 안 주면 기존 메쉬와 **비트동일**하다. 실물 상면/측면 사진에서 반폭·반높이
      프로파일을 재면(예: matrice4e 는 최대폭 스테이션이 **중앙보다 앞**, 꼬리는 배터리 평면,
      코는 뭉툭) 그 값을 넣어 실루엣을 맞춘다.
      hw_f/hh_f : xs=(-0.50,-0.30,-0.05,0.18,0.38,0.50)·L 에서의 반폭/반높이 (W·H 대비 비).
      zo_f      : 같은 스테이션의 중심선 z 오프셋(H 대비 비). None 이면 nose_drop 규약.

    ⭐⭐ 2026-08-16 (형상 감사) — `smooth_iters` 를 **선택 인자로 뺐다**. 기본 4 는 옛 값이라
      안 주면 전 기종 메쉬가 **비트동일**하다. 왜 손잡이가 필요한가:
        Taubin 스무딩은 로프트의 **양 끝 캡**(팬 삼각화 + 중심점)에서 테두리 링을 안쪽으로
        끌어당기고 중심점을 바깥으로 민다. 전 기종 실측(iters 0 ↔ 4):
          matrice4e  기수 반폭·반높이 41.02 × 36.88 → **23.42 × 21.31** (−43 %), 꼬리 27.31 ×
                     27.10 → 15.85 × 15.84 (−42 %), 셸 길이 234.60 → 236.91 (+2.31 mm)
          mavic4pro  꼬리 42.63 × 28.57 → 24.58 × 16.43   ·  mini5pro 꼬리 16.07 × 18.92 → 9.52 × 10.89
          phantom4   꼬리 50.97 × 24.59 → 29.53 × 14.27   ·  phantom3 기수 26.04 × 22.01 → 16.30 × 12.96
        즉 **끝단 스테이션의 실측값은 메쉬에 그대로 실리지 않는다** — matrice4e 의 «기수는
        뭉툭한 평면» 이라는 공식 CAD 측정(F04/F05)이 절반만 전달된다. 가운데 4 스테이션은
        표를 0.5 % 안에서 재현하므로 이 손실은 **끝단 전용**이다.
      ⚠ 그런데 방위평균 투영면적은 iters 0 ↔ 4 에서 **0.06 dB 밖에** 안 움직인다(전 기종
        0.00~0.06 dB). 즉 이것은 «레벨» 결함이 아니라 **기수/꼬리 정면 정반사 형상** 결함이다
        — 평판극한으로 보면 기수 정면 면적이 5264 → 1668 mm² 로 10 dB 급이지만, 그 각도는
        좁고 셸은 0.75 mm 유전체라 실제 기여는 그보다 훨씬 작다. 값은 아직 **안 바꿨다**
        (바꾸면 전 기종 σ 원장이 낡는다). 고칠 때는 이 인자로 기종별로 넣을 것."""
    xs = np.array([-0.50, -0.30, -0.05, 0.18, 0.38, 0.50]) * L
    hw = np.array(hw_f if hw_f is not None else (0.30, 0.46, 0.50, 0.44, 0.28, 0.10)) * W * tail_w
    hh = np.array(hh_f if hh_f is not None else (0.30, 0.46, 0.50, 0.46, 0.34, 0.16)) * H
    zo = np.array(zo_f if zo_f is not None
                  else (0.02, 0.01, 0.00, -0.04, -0.10, -nose_drop)) * H
    m = loft(spline_sections(xs, hw, hh, zo, n_pow=n_pow, n_sec=30, n_pts=72), n_pts=72)
    return smooth(m, iters=int(smooth_iters)) if int(smooth_iters) > 0 else m


#  기종별 셸 형상표 — **사진 실측**으로 얻은 것만 여기에 넣는다(없으면 _SHELL_DEFAULT).
#    fl/fw/fh   : 셸 (길이,폭,높이) = spec.body_l/w/h_mm 대비 비율
#    ndrop/npow : _body_folding 의 nose_drop · 단면 초타원 지수
#    cx0/cfrac/cfh : _canopy 의 x0 · frac · 높이배율(bh 대비)
#    hubf       : 암 시작 반경 = hubf · max(bl,bw)
#    hw/hh/zo   : _body_folding 단면 법칙(None 이면 공용 눈물방울)
_SHELL_DEFAULT = dict(fl=0.62, fw=0.40, fh=0.45, ndrop=0.22, npow=2.9,
                      cx0=-0.06, cfrac=0.62, cfh=1.0, hubf=0.30,
                      hw=None, hh=None, zo=None)
#  암 단면비 — (h_ratio, c_ratio). 없으면 (1.35, 0.55) = 옛 하드코딩 값(기존 메쉬 비트동일).
_ARM_SECTION = {
    "matrice4e": (2.00, 1.00),   # 원형 튜브 (정사각 + 최대 모서리반경 → 원)
    "phantom4":  (0.98, 0.40),   # 셸 일체 납작 페어링 (폭 대비 높이 ≈0.49)
    #  Mini/Mavic — 사진의 암은 **거의 원통에 가까운 살짝 눌린 타원**(정면컷의 세로 두께가
    #  평면컷의 가로 폭의 0.75~0.80). h_ratio 1.55 → 높이 = 폭×0.775.
    "mini5pro":  (1.55, 0.72),
    "mavic4pro": (1.55, 0.72),
    #  ⭐ Phantom 3 — 매뉴얼 정투영 정면도(`phantom3_m01…`, 0.74929 mm/px) 실측.
    #     암 끝 포드: 세로 16.3 mm ↔ 가로 31 mm(= 2·arm_r1) → h_ratio = 16.3/15.5 = 1.05.
    #     암 뿌리:   세로 20.6 mm ↔ 가로 43 mm(= 2·arm_r0) → h_ratio = 20.6/21.5 = 0.96.
    #     평균 1.00 을 쓴다(P4 의 0.98 과 우연히 거의 같다 — 상속이 아니라 **독립 실측**이다).
    #     c_ratio: 단면은 거의 스타디움(양 끝이 완전한 반원)이라 0.5·arm_r 에 가깝다 → 0.48.
    "phantom3":  (1.00, 0.48),
}
#  암 **폭**[mm] (뿌리, 끝). 없으면 대각비례(0.055/0.035·diag, 고정암은 0.085/0.060).
#  ⚠ matrice4e 는 여기 대신 스펙 필드 `arm_od_mm` 을 쓴다(등단면 원형 튜브).
_ARM_WIDTH = {
    "phantom4": (45.0, 30.0),
    #  ⭐ Phantom 3 — 공식 톱뷰 렌더 `phantom3_d03_official_top.png` **픽셀 실측**
    #     (축척 0.48122 mm/px = 모터 대각 350 mm ↔ 727.3 px, 대각 두 개가 0.08 % 로 일치).
    #     암 축(45°) 위 반경마다 **수직 현(chord)** 을 재면 (4 암 평균):
    #       r  80 → 41.5 · 100 → 35.5 · 110 → 32.0 · 120 → 29.4 · 130 → 26.3 ·
    #       140 → 25.8(최소) · 150 → 28.3 · 160 → 32.8 mm  (r=175 는 프롭이 가린다)
    #     실물 암은 **잘록한 허리 + 다시 벌어지는 모터 포드**라 우리 선형 테이퍼로는 정확히
    #     재현되지 않는다. 뿌리 43 / 끝 31 mm 는 그 측정열의 최소제곱 절충이다(중간이 +5 mm).
    "phantom3": (43.0, 31.0),
    #  ⭐ Mini 5 Pro — assets/photos/mini5pro/mini 5 pro_3.png(평면컷) **픽셀 실측**.
    #     축척 2.885 px/mm(앞뒤 모터 간격 440 px = 152.6 mm = 대각 275·cos 56.3°).
    #     암을 가로지르는 수직 절단의 현(chord) 13.5~16.3 px→mm 를 암 축과 y축이 이루는
    #     각으로 보정하면 **앞암 11.8 mm · 뒷암 12.2 mm** — 거의 등단면 12 mm 다.
    #     뿌리는 셸 페어링에 묻히므로 16.5(뿌리) → 11.6(끝) 로 완만한 테이퍼만 남긴다.
    #     ⛔ 옛 대각비례는 뿌리 30.2 · 끝 19.3 mm 로 **실측의 1.7~2.6배**였다(정면·평면 겹치기에서
    #        메쉬 암이 사진 암을 통째로 덮어버린 원인).
    "mini5pro": (16.5, 11.6),
    #  ⭐ Mavic 4 Pro — mavic 4 pro_2.png 정면컷의 암 두께 ≈19 mm 관측 + Mini 실측비 이전.
    #     Mini 의 실측 폭/대각 = 12.0/275 = 0.0436 을 같은 설계언어의 Mavic(441)에 적용하면
    #     19.2 mm 로, 사진 관측과 일치한다. **DERIVED**(Mini 실측의 스케일 이전).
    #     옛 대각비례는 뿌리 48.5 · 끝 24.4 mm 였다.
    "mavic4pro": (26.5, 18.5),
}
#  암 끝 아래 원뿔 다리(`_gear_arm_spikes`)의 길이[m]. 없으면 옛 하드코딩 0.072 (비트동일).
#  ⭐⭐ matrice4e 0.079 → **0.0529** (2026-08-04, F06). 근거는 DJI 공식 STEP
#     `assets/meshes/reference/matrice4-M4T_v2.step` 의 모서리(1D) 실측이다.
#       · 발 접지점 z = −59.82 (우리 좌표, z=0 = 암 허브 평면)
#       · 엔진식 foot = z_arm − h − d_tip/2 이고, arm_od 13.6 mm(F08) 에서
#         z_arm = 0.012·438.8·0.87 − 6.8 = −2.219 mm → h = 52.90 mm
#     ⭐ 독립검산: CAD 에서 다리 솔리드를 **직접 재면** 앞 54.7 · 뒤 45.4 (평균 50.05 mm) —
#        전혀 다른 경로가 3 mm 안에서 맞는다.
#     ⛔ 옛 0.079 는 측면사진에서 셸 crown 을 잘못 짚어 나온 사슬의 끝이었다(셸 89.1 · 벨리→발
#        38.5). 그 값으로는 모터 벨 중심이 접지면 위 99.4 mm 에 떠 있었다(실물 59.8).
#     ⚠ arm_od(F08)와 **짝**이다 — arm_od 20 mm 인 채로 이 값만 넣으면 발이 3.2 mm 어긋난다.
GEAR_SPIKE_H = {"matrice4e": 0.0529}
#  모터 벨 **밑동 z** [m]. 없으면 옛 하드코딩 0.014·diag (비트동일).
#  ⭐ phantom3 — 매뉴얼 정면도(0.74929 mm/px, z=0 = 암 허브 평면 = 행 393) 실측:
#     벨 아랫면 행 378.3 → z = +11.0 mm, 윗면 행 360 → z = +24.7 mm (높이 13.7 = motor_h_mm).
#     밑동 절반은 암 끝 포드 안에 묻힌다(포드 윗면 z ≈ +12.4) — 합집합으로 한 솔리드가 된다.
#  ⭐⭐ mini2 (2026-08-04, F3) — DJI 공식 GLB(WM161) 의 모터 벨 **파트 실측**:
#     앞 polySurface76 z [18.89, 25.99] · 뒤 polySurface96 z [−2.92, 4.83] → 두 밑동의
#     **평균 평면** (18.89 + (−2.92))/2 = 7.985 mm. 앞뒤 분리는 rotor_z_mm(±10.63)이 만든다.
#     ⛔ 엔진 기본식 0.014·diag = 2.982 mm 는 벨 밑동을 **암 축 위**에 놓아 벨의 절반을 암
#        속에 파묻는다. 실물은 벨이 암 끝 **위에** 앉는다(CAD: 암 축보다 앞 5.21 · 뒤 4.84 위).
#        비례식이 깨지는 이유는 Mini 2 의 암 단면(14.15 mm)이 213 mm 대각에 비해 이례적으로
#        굵기 때문이다.
MOTOR_BASE_Z = {"phantom3": 0.0110, "mini2": 0.007985}
#  ⭐⭐ 2026-08-07 (C1/P1) — **프롭이 앉는 면은 벨 윗면이다. 그 계산을 한 곳으로 모은다.**
#     [무엇이 틀렸나] 프롭을 놓는 코드(drones._arm_motor_dims)와 벨을 짓는 코드(이 파일)가
#     **서로 다른 바닥에서 높이를 셌다**. 프롭 쪽은 `motor_h + arm_t/2 + 6 mm` 라는 집안 규칙을
#     썼고 그 6 mm 와 arm_t/2 는 어떤 실측에도 닿아 있지 않았다. 벨 밑동(MOTOR_BASE_Z)은
#     **한 번도 읽지 않았다** — 그래서 벨을 움직여도 프롭이 안 따라오고, 어긋나도 예외가 안 난다.
#     실측 결과 프롭이 벨 위 3.6~13.2 mm 에 떠 있었다(outputs/meshdef_prop_gap.json).
#     [단일 출처] 이제 프롭 장착 z = `motor_bell_top_z_m()` + 스탠드오프 다. 앞으로 벨을 내리면
#     프롭이 저절로 따라온다.
#     [무엇을 맞추나 — C4 옵션 B] 프롭 **허브 밑면**을 벨 윗면에 앉힌다(스탠드오프 기본 0).
#     옵션 A(블레이드 중립면을 벨 윗면에)는 잔차가 0 이지만 허브가 벨 캡을 1.66 mm 파고들어
#     면이 겹치고, `build_drone` 은 prop 과 motor 를 **합집합하지 않아** 그 겹친 면이 살아남는다.
#     ⚠ 선언: 우리 블레이드 로프트는 뿌리가 장착면보다 0.7~2.2 mm 아래로 내려간다(익형 비틀림).
#       스탠드오프 0 이면 그만큼이 벨 캡과 겹친다 — 옛 6~13 mm 부양보다 훨씬 작지만 0 은 아니다.
MOTOR_BELL_TOP_Z_M = {
    #  벨을 **전용 분기**가 그리는 기체 — 일반식(MOTOR_BASE_Z + 벨높이)이 안 맞으므로 그 분기의
    #  상수를 여기 등록한다. 값을 바꾸면 프롭이 따라온다(그것이 이 표의 목적이다).
    "m350rtk": 0.011 + 0.030,      # 벨 밑동 = ARM_OD/2 = 11.0, 높이 motor_h_mm = 30.0 (m350rtk 분기)
    "typhoonh480": 0.0383,         # «벨 + 프롭 허브 축» 원통의 윗면(typhoonh480 분기, 메쉬 실측)
}
#  프롭 허브 밑면과 벨 윗면 사이 **틈** [m]. 없으면 0 = 허브가 벨 위에 그대로 앉는다.
PROP_STANDOFF_M = {
    #  ⚠ 아래 셋은 «고칠 근거가 없어서» 오늘 값을 그대로 재현하는 항목이다 — 이 라운드는
    #    이미 독립 앵커가 있는 기체를 건드리지 않는다. 셋 다 메쉬가 비트동일하게 남는다.
    "mini2":       0.0028075,   # 공식 GLB 앵커가 있는 기체. 옛 식(17.8925) − 벨 윗면(15.085).
    "m350rtk":     0.0060,      # 전용 분기 주석이 «prop_z 가 벨 위 6 mm 에 온다» 를 명시 설계.
    "typhoonh480": -0.0018,     # 프롭이 허브 축 원통 윗면보다 1.8 mm 아래에 있다. 축이 허브
                                #   보어를 관통하는 설계인지 결함인지 이 라운드가 가르지 않았다.
    #  x500v2 는 튜브 분기(OPEN_MOTOR_BASE_M + motor_h + 2 mm, 제조사 STEP 플랜지 실측)라
    #  이 표를 타지 않는다.
    #  ⭐ phantom3 = **1.55 mm** — 유일하게 «0 이 아닌» 근거가 있는 기체다(나사식 허브).
    #    P3 매뉴얼 정면도: 벨 윗면 z = +24.7, **블레이드면 z = +27.7** → 블레이드면이 벨 위 3.0 mm.
    #    우리 프롭의 블레이드 중립면은 장착면 위 **1.452 mm** 다(메쉬 실측, outputs/meshdef_prop_gap.json
    #    fleet_measurement.phantom3.blade_plane_offset_mm). 허브 밑면 기준으로 옮기면
    #      스탠드오프 = 3.0 − 1.452 = **1.548 → 1.55 mm** ⇒ 블레이드면이 도면의 +27.7 에 앉는다.
    "phantom3":    0.00155,
    #  ⭐⭐ mini5pro = **1.0 mm** (2026-08-10) — 물리 주장 아니라 **메쉬 유효성 간극**이다.
    #    [왜] 스탠드오프 0 이면 블레이드 뿌리 로프트(익형 비틀림)가 허브 밑면보다 내려가
    #      벨 캡 «솔리드 안»에 로터당 46 삼각형(프롭 면적 0.81 %)이 남는다. build_drone 은
    #      prop↔motor 를 합집합하지 않으므로 그 면적이 PO 에 **이중 계상**된다(예외 없음).
    #    [크기 근거] 벨 반경(14.3 mm) 안에서 뿌리가 장착면 아래로 내려가는 깊이 = **0.860 mm raw**
    #      (외형보정 sz 로 나눈 값, 네 로터 동일 — 이 라운드 실측, outputs/meshfix_mini5pro_overlap.json).
    #      1.0 mm 는 그것을 덮는 최소의 둥근 값이다(잉여 0.14 mm raw). 더 깊은 droop(−1.69 mm)은
    #      r 38.9 mm 까지의 블레이드 중간부라 벨 밖 허공이다 — 관통이 아니므로 여기서 안 다룬다.
    #    [실물과의 정합] Mini 5 Pro 는 프롭 z 의 mm 출처가 없다(meshgate_mini5pro.json — 정투영
    #      측면도·CAD 없음). 다만 나사식 프롭 가족의 실측 앵커 둘(mini2 공식 GLB **2.81 mm**,
    #      phantom3 매뉴얼 유도 **1.55 mm**)이 모두 이보다 크다 — 1.0 mm 는 실물 방향으로
    #      과장이 아니라 하한이다. 층차 (−7,+7,+7,−7)·부호(앞이 낮다)는 건드리지 않는다.
    "mini5pro":    0.0010,
}


def motor_bell_h_m(spec, diag) -> float:
    """모터 벨 **높이** [m]. 실측 부품치수(motor_h_mm)가 있으면 그것, 없으면 대각비례.
    ⭐ 2026-08-07 (C2/P2) — 예전에는 이 식이 **두 벌** 있었다: drones.py 가 0.045·diag,
      이 파일이 0.048·diag. 같은 물건의 높이를 두 파일이 다르게 믿었고, mavic4pro 에서는
      그 차이 1.32 mm 가 프롭 간격에 그대로 실렸다. 이제 여기 하나뿐이다(값은 0.048)."""
    mh = getattr(spec, "motor_h_mm", None)
    return float(mh) / 1000.0 if mh is not None else 0.048 * diag


def motor_bell_top_z_m(spec, diag) -> float:
    """모터 벨 **윗면** z [m] — 외형보정(sz) 전 raw, 암 허브 평면 기준, 로터별 dz 는 안 더한다.
    프롭 장착 z 와 벨 형상이 **같은 이 식**을 읽는다(위 MOTOR_BELL_TOP_Z_M 주석 참고)."""
    key = getattr(spec, "key", None)
    if key in MOTOR_BELL_TOP_Z_M:
        return float(MOTOR_BELL_TOP_Z_M[key])
    return MOTOR_BASE_Z.get(key, 0.014 * diag) + motor_bell_h_m(spec, diag)
#  암 끝 **페어링이 모터축보다 바깥으로 더 나가는 길이** [m]. 없으면 0 (암이 모터축에서 끝난다).
#  ⭐ phantom3 — D 등급(공표값에서 역산). 공표 평면 외형 289.0 mm 와 모터 대각 350 mm,
#     그리고 이 표의 암 끝 폭 31 mm 를 함께 풀면
#       144.5 = (175 + e)·cos45° + (31/2)·sin45°  →  e = 13.9 mm.
#     넣기 전 프레임 평면 bbox 는 275.8 mm 로 공표보다 **−4.6 %** 였다(옛 메쉬 283.9 도 같은 결함).
#     톱뷰 사진으로도 암 끝 포드가 모터축을 지나 더 나가는 것이 보이지만, 그 자리를 프롭이
#     가려 픽셀로는 못 잰다 → 실측이 아니라 유도값으로 적어 둔다.
#  ⭐⭐ mini2 (2026-08-04, F5) — **로터별 튜플**(rotor_deg 순서: 앞좌·뒤좌·뒤우·앞우).
#     스칼라를 쓰던 자리를 시퀀스도 받게 넓혔다 — phantom3 처럼 스칼라인 항목은 **비트동일**.
#     공식 GLB 를 암 **자기 축**을 따라 프로파일링한 값:
#       앞 polySurface201 (축 63.14°, 허브 r 98.43): 구조가 s = 113.52 까지 이어진다 →
#         모터축 바깥 **15.09 mm**. 기체 전체의 최대폭 정점 (50.34, 101.72, 13.11) 이 이 페어링이다.
#       뒤 polySurface101 (축 133.69°, 허브 r 116.92): s = 126.22 까지 → **9.30 mm**.
#         기체 최후방점 X = −90.28 을 이 페어링이 만든다.
#     ⚠ 남는 잔차(선언): `_arm_folding` 은 끝단면 폭을 2·arm_r1 = 9.0 mm 로 **일정하게** 쓸어
#       가는데 실물 페어링은 s=113.5 에서 6.96 mm 로 좁아져 있다 → 최대 |Y| 가 약 103.3 (실측
#       101.72) 이 되어 폭 오차가 −4.7 % → +1.6 % 로 부호만 바뀐다.
#       ⛔ 폭을 0 으로 만드는 13.33 mm 는 **채택하지 않는다** — 그건 부품에서 잰 값이 아니라
#          목표 엔벨로프에서 푼 값이다. 잔차는 나중에 끝단면을 테이퍼해서 없앤다.
ARM_TIP_OVERHANG = {"phantom3": 0.0139,
                    "mini2": (0.01509, 0.00930, 0.00930, 0.01509)}
#  ⭐⭐ 암·모터·다리의 z 평면이 **로터별 rotor_z_mm 을 따라가는** 기종 (2026-08-04, mini2 F1·F2·F4).
#     엔진 기본 동작은 네 암을 **한 평면**(0.012·diag)에 짓는 것이고, 그 상태에서 rotor_z_mm 은
#     `rotor_layout` 을 통해 **프로펠러만** 움직인다. Mini 2 는 앞 암 경첩이 동체 **위**, 뒤 암
#     경첩이 **아래**라 두 암 축이 실제로 21.44 mm 떨어져 있다(공식 GLB 실측: 앞 +13.68 ·
#     뒤 −7.76, 반값 10.72 ↔ 등록된 rotor_z_mm ±10.63 과 0.09 mm 일치).
#     ⛔ 키 게이트가 **필수**다 — mini5pro 도 rotor_z_mm 을 갖고 있어서 무조건 적용하면
#        그 기체 메쉬가 조용히 바뀐다. 표에 없는 기종은 전부 옛 동작 = 비트동일.
#     ⚠ 선언된 잔차: 실물 뒤 암은 바깥으로 갈수록 **내려간다**(r 60~70 에서 −5.89 → r 90~100
#       에서 −8.19). 균일 dz 는 엔진의 '끝이 올라가는' 기울기를 그대로 두므로 40 mm 구간에
#       2.5 mm 의 기울기 부호 오차가 남는다 — 이번 라운드가 고치지 않는 항목이다.
#     ⭐⭐ 2026-08-07 — **mini5pro 추가** (게이트 ②, outputs/meshgate_mini5pro.json).
#       Mini 5 Pro 도 앞뒤 암 경첩 높이가 다르다: DJI 공식 사용자 매뉴얼(한국어 2025-12-10판)
#       p.11 암 펼치기 도면과 p.14 부위도에서 **뒤 암은 동체 윗면, 앞 암은 동체 밑면**에서
#       펴진다(제품 렌더 _1 정면·_2 전좌상 두 컷도 같다). mini2 와 **부호가 반대**다.
#       그런데 표에 없어서 `rotor_z_mm` 이 프로펠러만 옮기고 암·벨·다리는 제자리였다 →
#       앞 프롭이 벨 **속에** 8.06 mm 박혀 삼각형 1324개가 이중계상되고 있었다(프롭 면적의 9.6 %).
#       표에 넣으면 암·모터 벨·다리가 로터 z 를 함께 따라가 관통이 0 이 된다.
