    rail_clamp_x_mm=50.0,          # VERIFIED — 하판 아래 레일 클램프(JIA-GUAN) x ±50
    #  BATTERY-MOUNTING-PLAT — 모서리 bbox 와 정점 bbox 가 **완전히 일치**한다:
    #  100.0 × 2.0 × 50.3, 중심 (0.01, −45.51, 0) → z −61.51.
